<?php if($c['driver']&&!$issue['blocking']&&!$c['blocked']):?><p><a href="<?=$h($base)?>/apps/delivery/index.php?issue=<?=$assignmentId?>&amp;new=1">Report another issue</a></p><?php endif;?></section>
